@import url("https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Noto+Sans+KR:wght@400;500;600;700;800&display=swap");

:root {
  color: #191f28;
  background: #f9fafb;
  font-family: "Noto Sans KR", "Manrope", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --ink: #191f28;
  --muted: #6b7684;
  --line: #e5e8eb;
  --surface: #ffffff;
  --canvas: #f9fafb;
  --navy: #191f28;
  --teal: #3182f6;
  --teal-deep: #1b64da;
  --teal-soft: #e8f3ff;
  --red: #f04452;
  --red-soft: #feebed;
  --yellow: #d08a00;
  --yellow-soft: #fff6e0;
  --purple: #7864b8;
  --purple-soft: #f2effc;
  --shadow: 0 8px 30px rgba(16, 24, 40, 0.07);
  --small-shadow: 0 2px 12px rgba(16, 24, 40, 0.05);
}

html[data-theme="dark"] {
  color-scheme: dark;
  --ink: #f4f6f8;
  --muted: #a5afbd;
  --line: #2b3441;
  --surface: #171c24;
  --canvas: #0f1218;
  --navy: #f4f6f8;
  --teal: #5b9df7;
  --teal-deep: #8dbdff;
  --teal-soft: #1a2b47;
  --red: #ff6b78;
  --red-soft: #3b1f29;
  --yellow: #f2c45e;
  --yellow-soft: #3b311c;
  --purple: #ad9bf2;
  --purple-soft: #2c2544;
  --shadow: 0 18px 48px rgba(0, 0, 0, .28);
  --small-shadow: 0 5px 20px rgba(0, 0, 0, .22);
  --mobile-canvas: #0f1218;
  --mobile-surface: #171c24;
  --mobile-ink: #f4f6f8;
  --mobile-muted: #a5afbd;
  --mobile-line: #2b3441;
  --mobile-blue: #5b9df7;
  --mobile-blue-deep: #8dbdff;
  --mobile-blue-soft: #1a2b47;
  --mobile-success: #55d5a5;
  --mobile-success-soft: #162b2a;
  --mobile-warning: #ff6b78;
  --mobile-warning-soft: #3b1f29;
  --mobile-shadow: 0 5px 20px rgba(0, 0, 0, .22);
}

* { box-sizing: border-box; }

html { min-height: 100%; background: var(--canvas); }

body { min-height: 100%; margin: 0; overflow-x: hidden; background: var(--canvas); -webkit-font-smoothing: antialiased; overscroll-behavior-y: none; touch-action: manipulation; }

#root { min-height: 100%; }

body.modal-open { overflow: hidden; }

button, input { font: inherit; }

button, a { -webkit-tap-highlight-color: transparent; touch-action: manipulation; }

button { cursor: pointer; }

button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible, summary:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; }

button:disabled { cursor: not-allowed; opacity: 0.6; }

.app-shell { min-height: 100vh; min-height: 100svh; padding-right: env(safe-area-inset-right); padding-bottom: env(safe-area-inset-bottom); padding-left: env(safe-area-inset-left); }

.app-error-boundary { display: grid; place-items: center; min-height: 100vh; padding: 24px; background: var(--canvas); }

.app-error-boundary-card { width: min(560px, 100%); padding: clamp(32px, 6vw, 56px); border: 1px solid #e1e9eb; border-radius: 28px; background: var(--surface); box-shadow: var(--shadow); text-align: center; }

.app-error-boundary-mark { display: grid; place-items: center; width: 56px; height: 56px; margin: 0 auto 24px; border-radius: 18px; color: #a95f5f; background: var(--red-soft); font-size: 30px; font-weight: 800; }

.app-error-boundary-card h1 { margin: 0; font-size: clamp(30px, 5vw, 44px); line-height: 1.18; letter-spacing: -0.045em; }

.app-error-boundary-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 32px; }

.app-error-boundary-actions .button { min-height: 54px; padding-inline: 24px; font-size: 16px; }

.draft-sync-notice { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-bottom: 16px; padding: 14px 16px; border: 1px solid #cfe4f0; border-radius: 13px; color: #4e7186; background: #f4fbff; box-shadow: var(--small-shadow); }

.draft-sync-notice-copy { display: flex; align-items: flex-start; gap: 10px; min-width: 0; }

.draft-sync-notice-copy > svg { flex: 0 0 auto; margin-top: 2px; color: #5b9ab5; }

.draft-sync-notice-copy strong, .draft-sync-notice-copy p { display: block; }

.draft-sync-notice-copy strong { color: #3e6478; font-size: 12px; }

.draft-sync-notice-copy p { margin: 4px 0 0; color: #6d8c9b; font-size: 10px; line-height: 1.55; }

.draft-sync-notice-actions { display: flex; align-items: center; flex: 0 0 auto; gap: 10px; }

@media (max-width: 640px) {
  .draft-sync-notice { align-items: stretch; flex-direction: column; }
  .draft-sync-notice-actions { justify-content: flex-end; }
}

.topbar { position: sticky; top: 0; z-index: 70; min-height: 76px; padding-top: env(safe-area-inset-top); border-bottom: 1px solid rgba(0, 27, 55, 0.06); background: rgba(255, 255, 255, 0.92); color: var(--ink); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); }

.topbar-inner { width: min(1240px, calc(100% - 48px)); min-height: 76px; margin: 0 auto; display: flex; align-items: center; gap: 48px; }

.brand { display: inline-flex; align-items: center; gap: 12px; padding: 0; border: 0; background: transparent; color: var(--ink); text-align: left; }

.brand-mark { display: grid; place-items: center; width: 38px; height: 38px; color: #fff; background: var(--teal); border-radius: 12px; font-size: 21px; box-shadow: 0 6px 14px rgba(49, 130, 246, 0.24); }

.brand strong { display: block; font-size: 16px; font-weight: 800; letter-spacing: -0.02em; }

.brand small { display: block; margin-top: 2px; color: var(--muted); font-size: 10px; letter-spacing: 0.03em; }

.topnav { display: flex; align-self: stretch; align-items: center; gap: 8px; }

.nav-link { position: relative; height: 100%; padding: 0 14px; border: 0; background: transparent; color: var(--muted); font-size: 13px; font-weight: 600; transition: color 140ms ease; }

.nav-link.active { color: var(--ink); }

.nav-link.active::after { position: absolute; right: 14px; bottom: 0; left: 14px; height: 3px; border-radius: 3px 3px 0 0; background: var(--teal); content: ""; }

.nav-link-with-badge { display: inline-flex; align-items: center; justify-content: center; }

.nav-alert-badge { position: absolute; top: 10px; right: 2px; display: inline-grid; place-items: center; min-width: 15px; height: 15px; padding: 0 3px; border: 2px solid #fff; border-radius: 999px; color: #fff; background: var(--red); font-family: "DM Mono", monospace; font-size: 7px; line-height: 1; box-shadow: 0 2px 5px rgba(0, 0, 0, .12); }

.topbar-status { display: flex; align-items: center; gap: 7px; margin-left: auto; color: var(--muted); font-size: 11px; }

.theme-toggle { display: inline-flex; align-items: center; gap: 6px; min-height: 36px; margin-left: auto; padding: 0 11px; border: 1px solid #e5e8eb; border-radius: 10px; color: #4e5968; background: #f2f4f6; font-size: 11px; font-weight: 700; transition: transform 120ms ease, border-color 140ms ease, background 140ms ease, color 140ms ease; }

.theme-toggle:hover:not(:disabled) { border-color: #cfdbe7; color: var(--teal-deep); background: #edf4fb; transform: translateY(-1px); }

.theme-toggle svg { width: 16px; height: 16px; color: var(--teal); }

.status-dot { width: 7px; height: 7px; border-radius: 50%; background: #2bae7b; box-shadow: 0 0 0 4px rgba(43, 174, 123, 0.14); }

.status-dot.loading { background: #e6a23c; box-shadow: 0 0 0 4px rgba(230, 162, 60, 0.16); }

.status-dot.degraded { background: var(--red); box-shadow: 0 0 0 4px rgba(240, 68, 82, 0.14); }

.topbar-status.degraded { color: var(--red); }

.topbar-status.loading { color: #b07514; }

.topbar-refresh-progress { width: min(1240px, calc(100% - 48px)); margin: 0 auto; padding: 9px 0 11px; border-top: 1px solid var(--line); }

.topbar-refresh-progress-heading { display: flex; align-items: center; justify-content: space-between; gap: 18px; }

.topbar-refresh-progress-heading > div { display: flex; align-items: baseline; gap: 10px; min-width: 0; }

.topbar-refresh-progress-kicker { flex: 0 0 auto; color: var(--teal); font-family: "DM Mono", monospace; font-size: 9px; letter-spacing: 0.14em; }

.topbar-refresh-progress-heading strong { overflow: hidden; color: var(--ink); font-size: 11px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }

.topbar-refresh-progress-count { flex: 0 0 auto; color: var(--teal); font-family: "DM Mono", monospace; font-size: 11px; font-weight: 500; }

.topbar-refresh-progress-track { height: 3px; margin-top: 7px; overflow: hidden; border-radius: 999px; background: #eef1f4; }

.topbar-refresh-progress-track > span { display: block; height: 100%; border-radius: inherit; background: var(--teal); transition: width 180ms ease; }

.topbar-refresh-progress > small { display: block; margin-top: 6px; overflow: hidden; color: var(--muted); font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }

.page-container { width: min(1240px, calc(100% - 48px)); margin: 0 auto; padding: 58px 0 90px; }

.route-stage { min-width: 0; }

.button:hover:not(:disabled) { transform: translateY(-1px); }

.eyebrow { display: flex; align-items: center; gap: 7px; margin: 0 0 11px; color: var(--teal-deep); font-family: "DM Mono", monospace; font-size: 10px; font-weight: 500; letter-spacing: 0.13em; text-transform: uppercase; }

h1, h2, h3, p { margin-top: 0; }

h1, h2, h3 { color: var(--ink); letter-spacing: -0.045em; }

h1 { margin-bottom: 16px; font-size: clamp(30px, 4vw, 53px); line-height: 1.12; }

h2 { margin-bottom: 8px; font-size: 24px; line-height: 1.25; }

h3 { margin-bottom: 7px; font-size: 16px; line-height: 1.35; }

p { color: var(--muted); line-height: 1.7; }

.button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 0 17px; border: 1px solid transparent; border-radius: 13px; font-size: 13px; font-weight: 700; transition: transform 120ms ease, box-shadow 160ms ease, background 140ms ease, border-color 140ms ease, color 140ms ease; }

.button:active:not(:disabled) { transform: scale(0.97); }

.button svg { flex: 0 0 auto; font-size: 16px; }

.button-primary { color: #fff; background: var(--teal); }

.button-primary:hover:not(:disabled) { background: var(--teal-deep); }

.button-secondary { color: #333d4b; background: #f2f4f6; }

.button-secondary:hover:not(:disabled) { background: #e8ebed; }

.button-light { color: #4e5968; background: #f2f4f6; }

.button-light:hover:not(:disabled) { background: #e8ebed; }

.button-ghost { color: var(--muted); background: transparent; }

.button-ghost:hover:not(:disabled) { background: #f2f4f6; }

.button-large { min-height: 52px; padding: 0 20px; border-radius: 16px; font-size: 14px; }

.button-small { min-height: 36px; padding: 0 12px; border-radius: 10px; font-size: 11px; }

.full-width { width: 100%; }

.back-link { display: inline-flex; align-items: center; gap: 6px; margin: 0 0 20px; padding: 0; border: 0; color: #6e808a; background: transparent; font-size: 12px; font-weight: 700; }

.back-link:hover { color: var(--teal-deep); }

.home-page { padding-top: 10px; }

.home-page-loading { display: flex; align-items: center; justify-content: center; min-height: 260px; gap: 8px; color: #78938e; font-size: 10px; }

.home-page-loading svg { color: var(--teal); }

.hero-section { display: grid; grid-template-columns: minmax(0, 1fr) minmax(360px, 0.86fr); gap: 90px; align-items: center; min-height: 460px; }

.hero-copy h1 span { color: var(--teal-deep); }

.hero-description { max-width: 555px; margin-bottom: 27px; font-size: 15px; }

.hero-actions { display: flex; flex-wrap: wrap; gap: 10px; }

.hero-secondary-action { color: #536473; background: #f3f5f7; }

.hero-secondary-action:hover:not(:disabled) { color: var(--ink); background: #e9edf1; }

.hero-demo-tools { width: fit-content; margin-top: 14px; }

.hero-demo-tools summary { display: inline-flex; align-items: center; min-height: 28px; padding: 0 2px; color: #84929a; cursor: pointer; font-size: 10px; font-weight: 700; list-style: none; }

.hero-demo-tools summary::-webkit-details-marker { display: none; }

.hero-demo-tools summary svg { width: 13px; height: 13px; margin-left: 4px; color: #aeb9bf; transition: transform 160ms ease; }

.hero-demo-tools[open] summary svg { transform: rotate(180deg); }

.hero-demo-tools > div { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 6px; }

.hero-demo-tools button { display: inline-flex; min-height: 32px; align-items: center; gap: 5px; padding: 0 10px; border: 1px solid #e3e8eb; border-radius: 9px; color: #6e7d86; background: #fff; font-size: 10px; font-weight: 600; transition: transform 120ms ease, background 140ms ease, border-color 140ms ease, color 140ms ease; }

.hero-demo-tools button:hover { border-color: #c9d9e0; color: var(--teal-deep); background: #f8fbff; }

.hero-demo-tools button:active { transform: scale(.97); }

.hero-demo-tools button svg { color: var(--teal); font-size: 13px; }

.hero-panel { position: relative; overflow: hidden; padding: 27px 25px 19px; border: 1px solid #dfe9e8; border-radius: 20px; background: #fff; box-shadow: var(--shadow); }

.hero-panel::before { position: absolute; top: -94px; right: -100px; width: 240px; height: 240px; border: 1px solid #e4f1ee; border-radius: 50%; content: ""; }

.panel-kicker { position: relative; margin-bottom: 22px; color: #a7b5b8; font-family: "DM Mono", monospace; font-size: 10px; letter-spacing: 0.13em; }

.preview-status { position: relative; display: flex; align-items: center; gap: 12px; padding-bottom: 20px; border-bottom: 1px solid var(--line); }

.status-icon { display: grid; place-items: center; width: 39px; height: 39px; border-radius: 12px; font-size: 21px; }

.status-icon.danger, .rule-icon.danger { color: var(--red); background: var(--red-soft); }

.status-icon.warning, .rule-icon.warning { color: var(--yellow); background: var(--yellow-soft); }

.status-icon.success, .rule-icon.success { color: var(--teal); background: var(--teal-soft); }

.preview-status strong { display: block; margin-bottom: 4px; color: var(--ink); font-size: 15px; }

.preview-status span:not(.status-icon) { display: block; color: var(--muted); font-size: 11px; }

.preview-rule { position: relative; display: flex; align-items: center; gap: 11px; padding: 17px 0; border-bottom: 1px solid #edf1f2; }

.preview-rule:last-of-type { border-bottom: 0; }

.rule-icon { display: grid; place-items: center; width: 28px; height: 28px; flex: 0 0 auto; border-radius: 8px; font-size: 15px; }

.preview-rule > div { min-width: 0; flex: 1; }

.preview-rule strong, .preview-rule small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.preview-rule strong { color: #43545e; font-size: 11px; font-weight: 700; }

.preview-rule small { margin-top: 4px; color: #8c9aa0; font-size: 10px; }

.preview-rule > svg { color: #a6b5b8; font-size: 13px; }

.preview-footer { display: flex; justify-content: space-between; margin-top: 12px; color: #a4b1b5; font-family: "DM Mono", monospace; font-size: 9px; }

.home-data-trust { margin-top: 28px; padding: 22px 24px 20px; border: 1px solid var(--line); border-radius: 16px; background: #fff; box-shadow: var(--small-shadow); }

.home-data-trust-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }

.home-data-trust-heading h2 { margin-bottom: 5px; font-size: 16px; }

.home-data-trust-heading p:not(.eyebrow) { margin-bottom: 0; color: var(--muted); font-size: 11px; }

.home-data-trust-status { display: inline-flex; align-items: center; gap: 8px; flex: 0 0 auto; padding: 8px 10px; border: 1px solid #cdebe4; border-radius: 999px; color: #4f8579; background: #f1fbf8; font-size: 10px; font-weight: 700; }

.home-data-trust-status.loading, .home-data-trust-status.review { border-color: #f0dfb3; color: #9b7836; background: #fffaf0; }

.home-data-trust-status.degraded { border-color: #f1caca; color: #ad5c5c; background: #fff5f5; }

.home-data-trust-status.loading .status-dot, .home-data-trust-status.review .status-dot { background: #e6bc63; box-shadow: 0 0 0 4px rgba(230, 188, 99, 0.14); }

.home-data-trust-status.degraded .status-dot { background: var(--red); box-shadow: 0 0 0 4px rgba(214, 109, 109, 0.14); }

.home-data-trust-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; margin-top: 20px; }

.home-data-trust-grid > div { min-width: 0; padding: 13px 14px; border: 1px solid #edf1f2; border-radius: 11px; background: #f9fafb; }

.home-data-trust-grid span, .home-data-trust-grid strong, .home-data-trust-grid small { display: block; }

.home-data-trust-grid span { overflow: hidden; color: #7b8b91; font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }

.home-data-trust-grid strong { margin-top: 7px; overflow: hidden; color: var(--ink); font-size: 17px; text-overflow: ellipsis; white-space: nowrap; }

.home-data-trust-grid small { margin-top: 5px; overflow: hidden; color: #9aa7ac; font-size: 9px; line-height: 1.45; text-overflow: ellipsis; white-space: nowrap; }

.home-data-trust-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; margin-top: 12px; padding-top: 12px; border-top: 1px solid #edf3f1; }

.home-data-trust-actions .button { display: inline-flex; align-items: center; gap: 5px; min-height: 29px; }

.home-data-trust-actions .button svg { flex: 0 0 auto; color: var(--teal); }

.home-data-trust-loading { display: flex; align-items: flex-start; gap: 7px; margin: 14px 0 0; color: #84949a; font-size: 10px; line-height: 1.5; }

.home-data-trust-loading svg { flex: 0 0 auto; color: #c89943; }

.home-catalog-cache { margin-top: 16px; padding: 18px 20px 17px; border: 1px solid #e5e8eb; border-radius: 15px; background: linear-gradient(135deg, #f9fafb 0%, #fff 78%); box-shadow: var(--small-shadow); }

.home-catalog-cache.empty { border-style: dashed; background: #fff; box-shadow: none; }

.home-catalog-cache-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }

.home-catalog-cache-heading h2 { margin-bottom: 5px; color: #5d716f; font-size: 15px; }

.home-catalog-cache-heading p:not(.eyebrow) { max-width: 720px; margin: 0; color: #899b99; font-size: 10px; line-height: 1.5; }

.home-catalog-cache-heading > span { flex: 0 0 auto; padding: 6px 8px; border-radius: 5px; color: #6b7684; background: #e5f7ee; font-family: "DM Mono", monospace; font-size: 8px; font-weight: 700; }

.home-catalog-cache-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; margin-top: 14px; }

.home-catalog-cache-item { display: grid; gap: 4px; min-width: 0; padding: 10px; border: 1px solid #e4ecea; border-radius: 9px; background: #fff; }

.home-catalog-cache-item > div { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }

.home-catalog-cache-item > div span, .home-catalog-cache-item > div strong, .home-catalog-cache-item small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.home-catalog-cache-item > div span { color: #7d918d; font-size: 9px; }

.home-catalog-cache-item > div strong { color: #586e6a; font-family: "DM Mono", monospace; font-size: 12px; }

.home-catalog-cache-item > em { width: fit-content; padding: 2px 4px; border-radius: 3px; color: #4e8979; background: #e5f7ee; font-size: 6.5px; font-style: normal; font-weight: 700; }

.home-catalog-cache-item.aging > em { color: #96733a; background: #fff1cf; }

.home-catalog-cache-item.stale > em, .home-catalog-cache-item.unknown > em { color: #9f6565; background: #fce8e8; }

.home-catalog-cache-item small { color: #9aa9a6; font-family: "DM Mono", monospace; font-size: 6.5px; }

.home-catalog-cache-item .text-button { justify-self: start; margin-top: 2px; color: #6f8b86; font-size: 7px; }

.home-catalog-cache-item .text-button:disabled { cursor: default; opacity: .5; }

.home-catalog-cache-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 9px; margin-top: 10px; padding-top: 9px; border-top: 1px solid #e8efed; }

.home-catalog-cache-actions .button { margin: 0; color: #708581; border-color: #e5e8eb; background: #fff; }

.home-catalog-cache-actions p, .home-catalog-cache-empty, .home-catalog-cache-message { display: flex; align-items: flex-start; gap: 5px; margin: 0; color: #98a8a4; font-size: 7px; line-height: 1.45; }

.home-catalog-cache-actions p { flex: 1; min-width: 200px; }

.home-catalog-cache-actions p svg, .home-catalog-cache-empty svg, .home-catalog-cache-message svg { flex: 0 0 auto; margin-top: 1px; color: #76a294; }

.home-catalog-cache-empty { margin-top: 12px; }

.home-catalog-cache-message { margin-top: 9px; padding-top: 8px; border-top: 1px solid #e8efed; color: #628b80; }

.home-draft-resume { margin-top: 16px; padding: 22px 24px 20px; border: 1px solid #e5e8eb; border-radius: 16px; background: linear-gradient(135deg, #f9fafb 0%, #fff 68%); box-shadow: var(--small-shadow); }

.home-draft-resume-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; }

.home-draft-resume-heading h2 { margin-bottom: 5px; font-size: 16px; }

.home-draft-resume-heading p:not(.eyebrow) { margin-bottom: 0; color: var(--muted); font-size: 11px; }

.home-draft-result { display: inline-flex; align-items: center; gap: 8px; flex: 0 0 auto; padding: 8px 10px; border: 1px solid #cdebe4; border-radius: 999px; color: #4f8579; background: #fff; font-size: 10px; font-weight: 700; }

.home-draft-result.incompatible { border-color: #f1caca; color: #ad5c5c; }

.home-draft-result.needs_review, .home-draft-result.review { border-color: #f0dfb3; color: #9b7836; }

