}

/* --------------------------------------------------------------------------
   Mobile product redesign
   --------------------------------------------------------------------------
   The existing desktop surfaces stay available for wide screens. At the
   handset breakpoint the shell becomes a real app surface: compact app bar,
   content-first scrolling, grouped list rows, and a safe-area aware tab bar.
*/

.mobile-editor-surface,
.mobile-bottom-nav,
.mobile-more-layer,
.mobile-home-view,
.mobile-header-menu { display: none; }

@media (max-width: 760px) {
  :root {
    --mobile-canvas: #f9fafb;
    --mobile-surface: #ffffff;
    --mobile-ink: #191f28;
    --mobile-muted: #6b7684;
    --mobile-line: #e5e8eb;
    --mobile-blue: #3182f6;
    --mobile-blue-deep: #1b64da;
    --mobile-blue-soft: #e8f3ff;
    --mobile-success: #1fae72;
    --mobile-success-soft: #e5f7ee;
    --mobile-warning: #f04452;
    --mobile-warning-soft: #feebed;
    --mobile-shadow: 0 2px 10px rgba(16, 24, 40, .05);
  }

  html,
  body { background: var(--mobile-canvas); color: var(--mobile-ink); }

  body { font-family: "Noto Sans KR", "Manrope", sans-serif; }

  button,
  input,
  select { font-size: 14px; }

  button { min-height: 44px; }

  .app-shell {
    min-height: 100svh;
    padding-right: 0;
    padding-bottom: calc(86px + env(safe-area-inset-bottom));
    padding-left: 0;
