  .generator-brief-input textarea,
  .generator-brief-preview,
  .generator-brief-matches span,
  .generator-brief-guidance,
  .generator-brief-guidance-item,
  .generator-preset,
  .generator-saved-preset-editor input,
  .generator-preset-import-preview,
  .generator-saved-preset-list article,
  .generator-form select,
