  .generator-checkbox,
  .generator-variants-table-wrap,
  .generator-decision-summary,
  .generator-decision-card,
  .generator-budget-table-wrap,
  .generator-budget-deltas,
  .generator-budget-score-chart
) {
  border-color: var(--line) !important;
  color: var(--ink) !important;
  background: #202631 !important;
}

html[data-theme="dark"] :where(
