  .generator-brief-guidance-item.actionable:hover:not(:disabled),
  .generator-decision-card.selected
) { border-color: #3f6da8 !important; background: var(--teal-soft) !important; }

html[data-theme="dark"] .button-brief-ghost { border-color: var(--line) !important; color: var(--ink) !important; background: #202631 !important; }

html[data-theme="dark"] .generator-budget-ladder,
html[data-theme="dark"] .generator-variants { border-color: var(--line) !important; background: var(--surface) !important; }

html[data-theme="dark"] :where(.generator-budget-ladder-export-actions .text-button, .generator-budget-share-preview, .generator-budget-share-preview input) {
  border-color: var(--line) !important;
  color: var(--ink) !important;
  background: #202631 !important;
}

html[data-theme="dark"] :where(
  .catalog-results-heading > span,
  .catalog-detail-heading > img,
  .catalog-detail-heading > svg,
  .catalog-detail-badges span,
  .catalog-price-evidence,
  .catalog-benchmark-evidence-source,
  .catalog-benchmark-evidence-meta,
