  .quality-badge.incomplete,
  .catalog-price-evidence.reference,
  .catalog-price-evidence.recorded
) {
  border-color: #5a4b29 !important;
  color: var(--yellow) !important;
  background: var(--yellow-soft) !important;
}

html[data-theme="dark"] :where(
  .freshness-badge.fresh,
  .quality-badge.live,
  .quality-badge.seed,
  .quality-badge.manual,
  .catalog-price-evidence.live,
  .catalog-price-evidence.manual
) {
  border-color: #254c45 !important;
