html[data-theme="dark"] :where(html, body, #root, .app-shell, .page-container, .topbar, .mobile-bottom-nav, .theme-toggle, .mobile-header-menu, .mobile-recommend-card, .mobile-secondary-action, .component-card, .catalog-part-card, .accessory-item, .suggestion-card, .result-hero, .metric-card, .purchase-decision-gate, .build-action-center) {
